"""Request syntax and aggregate resource-domain validation."""
import json
import re

ID = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")
MAX_BYTES = 64*1024**2
MAX_DEPTH = 32
MAX_CONTAINERS = 300000
VALUE_MAX = 3028
PAD = 1514
ALLOWED_VALUES = frozenset(range(VALUE_MAX+1))
ACT_MAX = 1000000
STRUCTURAL = re.compile(rb'["\\\[\]{}]')
_KEEP = b'"\\[]{}'
_DELETE = bytes(b for b in range(256) if chr(b) not in _KEEP.decode('ascii'))


def require(condition):
    if not condition:
        raise ValueError('invalid_request')


def integer(value, lo, hi):
    return type(value) is int and lo <= value <= hi


def identifier(value):
    return type(value) is str and ID.fullmatch(value) is not None


def keys(obj, fields):
    return type(obj) is dict and set(obj) == set(fields.split())


def fraction(value):
    return (type(value) is list and len(value) == 2 and
            integer(value[0], 0, 1000000) and integer(value[1], 1, 1000000))


def unique(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result)
        result[key] = value
    return result


def constant(_):
    raise ValueError('invalid_request')


def float_token(_):
    # Integer fields require JSON integer tokens: 3.0 / 3e0 are invalid.
    raise ValueError('invalid_request')


def real_values(values):
    try:
        return values[:values.index(PAD)]
    except ValueError:
        return values


def check_values(values, lo_len, hi_len):
    """Encoded value vectors: bounded integers, padding only as a suffix."""
    if type(values) is not list or not lo_len <= len(values) <= hi_len:
        raise ValueError('invalid_request')
    try:
        seen = set(values)
    except TypeError:
        raise ValueError('invalid_request') from None
    if not seen <= ALLOWED_VALUES:
        raise ValueError('invalid_request')
    for value in seen:
        if type(value) is not int:
            raise ValueError('invalid_request')
    if PAD in seen:
        first = values.index(PAD)
        if set(values[first:]) != {PAD}:
            raise ValueError('invalid_request')


def check_activation(values):
    """Activation maps: bounded non-negative integers."""
    if type(values) is not list:
        raise ValueError('invalid_request')
    try:
        seen = set(values)
    except TypeError:
        raise ValueError('invalid_request') from None
    for value in seen:
        if type(value) is not int or not 0 <= value <= ACT_MAX:
            raise ValueError('invalid_request')


def check_depth(root):
    """Iterative container-nesting bound (root object is depth 1)."""
    if type(root) is not dict and type(root) is not list:
        return
    order = [(root, 1)]
